import json,hashlib
H=lambda b:hashlib.sha256(b).hexdigest()
def encode(record):
    b=(json.dumps(record,ensure_ascii=False,separators=(',',':'))+'\r\n').encode('utf-8')
    if len(b.decode('utf-8'))>9744: raise ValueError('OUTPUT_BOUND')
    return b
def resolve(refs,actual,frozen,sources):
    out={k:bytearray() for k in sources}
    if len(refs)!=23: raise ValueError('COUNT')
    for i,(n,op,size,sha,mid) in enumerate(refs,1):
        if type(n)is not int or (n,op,mid)!=(i,f'b-frame{i:02d}',f'f{i:02d}'): raise ValueError('REF')
        raw=actual[op] # ACTUAL complete producer bytes, boundary separately proven
        f=frozen[i-1]
        if len(raw)!=size or H(raw)!=sha or size!=f['utf8Bytes'] or sha!=f['sha256']: raise ValueError('PIN')
        v=strict_json(raw) # closed duplicate/nonfinite/type-rejecting decoder required
        if v['frame']!=i or len(v['parts'])!=len(f['parts']): raise ValueError('PARTS')
        for a,p in zip(v['parts'],f['parts']):
            if {k:a[k] for k in p}!=p: raise ValueError('MAP')
            k=a['rowId'];x=a['offset'];y=a['end'];b=a['text'].encode('utf-8')
            if type(x)is not int or type(y)is not int or x!=len(out[k]) or y-x!=len(b) or H(b)!=a['pieceSHA256'] or sources[k][x:y]!=b: raise ValueError('SOURCE')
            out[k].extend(b)
    if any(bytes(out[k])!=sources[k] for k in sources): raise ValueError('COVERAGE')
    return True

def strict_json(raw):
    def pairs(items):
        d={}
        for k,v in items:
            if k in d: raise ValueError('DUPLICATE_KEY')
            d[k]=v
        return d
    def bad(v): raise ValueError('NONFINITE')
    return json.loads(raw.decode('utf-8',errors='strict'),object_pairs_hook=pairs,parse_constant=bad)
def select_history(mcp,chat,turn,expected_commands):
    if mcp.get('isError') or len(mcp['content'])!=1 or mcp['content'][0]['type']!='text': raise ValueError('MCP')
    raw=mcp['content'][0]['text'].encode('utf-8',errors='strict')
    v=strict_json(raw)
    if v['thread']['id']!=chat: raise ValueError('CHAT')
    ts=[t for t in v['turns'] if t['id']==turn]
    if len(ts)!=1: raise ValueError('SELECTED_TURN')
    t=ts[0]
    if t['status']!='completed' or t['error'] is not None: raise ValueError('TURN_NOT_CLOSED')
    cmds=[a for a in t['items'] if a['type']=='commandExecution']
    if len(cmds)!=len(expected_commands): raise ValueError('OPERATION_COUNT')
    seen=set();out={}
    for op,expected,a in zip(expected_commands,expected_commands.values(),cmds):
        if set(a)!=set(('type','id','command','cwd','status','exitCode','durationMs','output')): raise ValueError('ACTUAL_FIELDS')
        if set(a['output'])!=set(('text','truncated')): raise ValueError('OUTPUT_FIELDS')
        if a['id'] in seen or not a['id'] or a['output']['truncated'] is not False: raise ValueError('INCOMPLETE')
        seen.add(a['id'])
        if a['command']!=expected or len(a['command'])>20000: raise ValueError('ACTUAL_COMMAND_DIFFERENCE')
        if a['status']!='completed' or type(a['exitCode'])is not int or a['exitCode']!=0: raise ValueError('EXECUTION_FAILED')
        txt=a['output']['text'];bb=txt.encode('utf-8',errors='strict')
        if len(txt)>10000: raise ValueError('OUTPUT_LIMIT')
        out[op]={'actual':a,'returnedTextBytes':len(bb),'returnedTextSHA256':H(bb),'actorChatId':chat,'actorTurnId':turn}
    # Older-turn pagination does not negate complete selected-turn records.
    return {'rawReplyUTF8':raw.decode('utf-8'),'rawReplyBytes':len(raw),'rawReplySHA256':H(raw),'selectedTurn':t,'operations':out,'olderTurnsPage':v['page']}
